INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1150, 'email', 'ˈiːmeɪl', 'noun', '{"zh-TW":["電子郵件；電子信件","郵件"],"en":["a message sent electronically","an electronic message system"]}', NULL, 'send an email/check email', '[{"en":"Please check your email for the attachment.","zh-TW":"請查看您的電子郵件以獲取附件。"}]', '{"verb":"email","adjective":"email-based"}', NULL, 2, 1150, NULL),
(1151, 'embargo', '/ɪmˈbɑːrɡəʊ/', 'noun', '{"zh-TW":["禁運令；貿易禁令"],"en":["an official ban on trade with a particular country"]}', NULL, 'impose an embargo / lift an embargo', '[{"en":"The government imposed an embargo on the export of technology.","zh-TW":"政府對技術出口實施了禁運令。"},{"en":"Lifting the trade embargo opened new market opportunities.","zh-TW":"解除貿易禁令開闢了新的市場機會。"}]', '{"verb":"embargo"}', NULL, 3, 1151, NULL),
(1152, 'embark', '/ɪmˈbɑːrk/', 'verb', '{"zh-TW":["登船；開始"],"en":["to get on a ship or aircraft"]}', NULL, 'embark on a journey / embark passengers', '[{"en":"Passengers began to embark at noon.","zh-TW":"乘客在中午開始登船。"},{"en":"They embarked on an exciting new adventure.","zh-TW":"他們踏上了令人興奮的新冒險。"}]', '{"noun":"embarkation"}', NULL, 2, 1152, NULL),
(1153, 'embarkation', '/ˌɛmbɑːrˈkeɪʃən/', 'noun', '{"zh-TW":["登船；登機"],"en":["the action of getting on a ship or aircraft"]}', NULL, 'embarkation point / embarkation card', '[{"en":"Embarkation will begin at the main gate.","zh-TW":"登船將在主閘口開始。"},{"en":"Please complete the embarkation card before arrival.","zh-TW":"請在抵達前填妥入境卡。"}]', '{"verb":"embark"}', NULL, 4, 1153, NULL),
(1154, 'embarrassed', '/ɪmˈbærəst/', 'adjective', '{"zh-TW":["尷尬的；難為情的"],"en":["feeling ashamed or shy"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"barrass","meaning":"bar/obstruct (阻礙)"},"suffix":{"text":"-ed","meaning":"feeling (感受)"},"logic":"感覺被阻礙住的，即「尷尬的」。"}', 'feel embarrassed / embarrassed about', '[{"en":"He was embarrassed by his mistake.","zh-TW":"他因犯錯而感到尷尬。"},{"en":"She felt embarrassed in front of everyone.","zh-TW":"她在眾人面前感到難為情。"}]', '{"noun":"embarrassment","adjective":"embarrassing","verb":"embarrass"}', NULL, 4, 1154, NULL),
(1155, 'embrace', '/ɪmˈbreɪs/', 'verb', '{"zh-TW":["擁抱；接受"],"en":["to accept willingly; to hold closely"]}', NULL, 'embrace change/technology', '[{"en":"Companies must embrace new technology.","zh-TW":"企業必須擁抱新技術。"},{"en":"She embraced the opportunity eagerly.","zh-TW":"她熱切地接受了這個機會。"}]', '{"noun":"embrace","verb":"embrace"}', NULL, 3, 1155, NULL),
(1156, 'emerge', '/ɪˈmɜːrdʒ/', 'verb', '{"zh-TW":["出現；浮現"],"en":["to come into view; to become known","to come into view or existence"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"merge","meaning":"dip/plunge (浸入)"},"logic":"從水中浮出，即「出現」。"}', 'emerge as/from; emerge from / emerging market / emerge as', '[{"en":"New competitors are emerging in the market.","zh-TW":"市場上出現了新的競爭者。"},{"en":"The company emerged as a market leader.","zh-TW":"該公司成為市場領導者。"},{"en":"New evidence emerged during the investigation.","zh-TW":"調查期間浮現了新證據。"},{"en":"She emerged as the leading candidate.","zh-TW":"她脫穎而出成為領先的候選人。"}]', '{"noun":"emergence","verb":"emerge","adjective":"emerging/emergent"}', NULL, 2, 1156, NULL),
(1157, 'emergency', '/ɪˈmɜːrdʒənsi/', 'noun', '{"zh-TW":["緊急情況"],"en":["a serious unexpected situation requiring immediate action"]}', NULL, 'in case of emergency', '[{"en":"Call 911 in case of an emergency.","zh-TW":"緊急情況下請撥打911。"},{"en":"An emergency meeting was called.","zh-TW":"召開了緊急會議。"}]', '{"noun":"emergency","adjective":"emergency"}', NULL, 3, 1157, 343),
(1158, 'emission', '/ɪˈmɪʃən/', 'noun', '{"zh-TW":["排放；排放物"],"en":["the production and discharge of something, especially gas"]}', NULL, 'carbon/greenhouse emissions', '[{"en":"The factory must reduce its carbon emissions.","zh-TW":"工廠必須減少碳排放。"},{"en":"Emission standards are becoming stricter.","zh-TW":"排放標準越來越嚴格。"}]', '{"noun":"emission","verb":"emit"}', NULL, 3, 1158, NULL),
(1159, 'emotion', '/ɪˈmoʊʃn/', 'noun', '{"zh-TW":["情緒；情感"],"en":["a strong feeling such as joy, anger, or sadness"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"mot","meaning":"move (移動)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"從內心移動出來的感覺，即「情緒」。"}', 'strong emotion / show emotion / mixed emotions', '[{"en":"She couldn''t hide her emotions.","zh-TW":"她無法隱藏自己的情緒。"},{"en":"The movie evoked strong emotions.","zh-TW":"這部電影激發了強烈的情感。"}]', '{"adjective":"emotional","adverb":"emotionally"}', NULL, 3, 1159, NULL),
(1160, 'empathy', '/ˈempəθi/', 'noun', '{"zh-TW":["同理心"],"en":["the ability to understand and share another''s feelings"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"進入他人感受中，即「同理心」。"}', 'show empathy / lack of empathy', '[{"en":"A good therapist shows empathy toward patients.","zh-TW":"好的治療師對病人展現同理心。"},{"en":"Empathy is important in building relationships.","zh-TW":"同理心在建立關係中很重要。"}]', '{"adjective":"empathetic","verb":"empathize"}', NULL, 3, 1160, NULL),
(1161, 'emphasis', '/ˈemfəsɪs/', 'noun', '{"zh-TW":["強調；重點"],"en":["special importance given to something"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"phas","meaning":"show (展現)"},"suffix":{"text":"-is","meaning":"state (狀態)"},"logic":"在其中展現出重要性，即「強調」。"}', 'place/put emphasis on; place emphasis on / with emphasis / special emphasis', '[{"en":"The company places great emphasis on quality.","zh-TW":"公司非常重視品質。"},{"en":"There is growing emphasis on sustainability.","zh-TW":"對永續發展的重視日益增長。"},{"en":"The school places emphasis on creative thinking.","zh-TW":"學校強調創意思考。"},{"en":"She spoke with great emphasis.","zh-TW":"她說話時特別加重語氣。"}]', '{"noun":"emphasis","verb":"emphasize","adjective":"emphatic"}', NULL, 3, 1161, NULL),
(1162, 'emphasize', '/ˈɛmfəsaɪz/', 'verb', '{"zh-TW":["強調；重視"],"en":["to give special attention to something"]}', NULL, 'emphasize the importance / emphasize key points', '[{"en":"The manager emphasized the importance of meeting deadlines.","zh-TW":"經理強調了按時完成工作的重要性。"},{"en":"Please emphasize the key benefits in your presentation.","zh-TW":"請在您的簡報中強調主要優勢。"}]', '{"noun":"emphasis","adjective":"emphatic"}', NULL, 3, 1162, NULL),
(1163, 'employ', '/ɪmˈplɔɪ/', 'verb', '{"zh-TW":["僱用；使用","雇用；運用"],"en":["to give work to someone; to use","to give work to someone","to make use of"]}', '{"prefix":{"text":"em-","meaning":"in (在內)"},"root":{"text":"ploy","meaning":"fold/use (使用)"},"logic":"把人用進來，即「雇用」。"}', 'employ staff/methods; employ staff / employ a strategy / currently employed', '[{"en":"The company employs over 5,000 people.","zh-TW":"該公司僱用了5000多人。"},{"en":"We employ various strategies to boost sales.","zh-TW":"我們使用各種策略來促進銷售。"},{"en":"The company employs over 500 people.","zh-TW":"公司雇用超過500人。"},{"en":"She employed a new strategy to solve the problem.","zh-TW":"她運用了新策略來解決問題。"}]', '{"noun":"employment/employee/employer","verb":"employ","noun2":"employee","noun3":"employer"}', NULL, 2, 1163, 344),
(1164, 'employee', 'ɛmˈplɔɪiː', 'noun', '{"zh-TW":["員工；雇員","職員"],"en":["a person working for a company","a worker"]}', NULL, 'full-time employee/employee benefits', '[{"en":"Employees must complete safety training.","zh-TW":"員工必須完成安全培訓。"}]', '{"verb":"employ","noun":"employer","adjective":"employed"}', NULL, 3, 1164, 27),
(1165, 'employer', 'ɪmˈplɔɪər', 'noun', '{"zh-TW":["雇主；僱主","用人單位"],"en":["a person or company that employs","an organization that hires"]}', NULL, 'current employer/prospective employer', '[{"en":"Please provide your current employer''s details.","zh-TW":"請提供您目前雇主的詳細信息。"}]', '{"verb":"employ","noun":"employment","adjective":"employing"}', NULL, 3, 1165, NULL),
(1166, 'empower', '/ɪmˈpaʊər/', 'verb', '{"zh-TW":["賦予權力；使能夠"],"en":["to give someone authority or confidence"]}', NULL, 'empower employees/women', '[{"en":"The training empowers employees to make decisions.","zh-TW":"培訓賦予員工做決定的能力。"},{"en":"Technology empowers small businesses to compete.","zh-TW":"技術使小企業能夠參與競爭。"}]', '{"noun":"empowerment","verb":"empower"}', NULL, 3, 1166, 737),
(1167, 'empowered', 'ɪmˈpaʊərd', 'adjective', '{"zh-TW":["被授權的；有能力的","賦權的"],"en":["given authority to act","made capable"]}', NULL, 'empowered employees/empowered to decide', '[{"en":"Managers are empowered to make decisions.","zh-TW":"經理們被授權做決定。"}]', '{"verb":"empower","noun":"empowerment"}', NULL, 3, 1167, NULL),
(1168, 'empty', '/ˈɛmpti/', 'adjective', '{"zh-TW":["空的"],"en":["containing nothing; not filled"]}', NULL, 'empty space / empty promise', '[{"en":"The meeting room is empty now.","zh-TW":"會議室現在是空的。"},{"en":"Don''t make empty promises.","zh-TW":"別做空洞的承諾。"}]', '{"adjective":"empty","verb":"empty","noun":"emptiness"}', NULL, 2, 1168, NULL),
(1169, 'enable', '/ɪˈneɪbəl/', 'verb', '{"zh-TW":["使能夠；啟用"],"en":["to make possible or allow","to make possible or provide the means for"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"able","meaning":"able (能夠)"},"logic":"使其能夠，即「使能夠」。"}', 'enable + 人 + to; enable access / enable growth', '[{"en":"The software enables users to track expenses.","zh-TW":"該軟體使用戶能夠追蹤支出。"},{"en":"This funding will enable further research.","zh-TW":"這筆資金將使進一步研究成為可能。"},{"en":"Technology enables people to work from home.","zh-TW":"科技使人們能在家工作。"},{"en":"The grant enabled her to continue her research.","zh-TW":"這筆補助使她能繼續研究。"}]', '{"verb":"enable","adjective":"enabling"}', NULL, 2, 1169, 345),
(1170, 'enact', '/ɪˈnækt/', 'verb', '{"zh-TW":["制定；頒布"],"en":["to make a bill into law"]}', NULL, 'enact legislation/a policy', '[{"en":"The government enacted new environmental regulations.","zh-TW":"政府制定了新的環境法規。"},{"en":"The law was enacted in 2020.","zh-TW":"該法律於2020年頒布。"}]', '{"noun":"enactment","verb":"enact"}', NULL, 2, 1170, NULL),
(1171, 'enclosed', '/ɪnˈkləʊzd/', 'adjective', '{"zh-TW":["附件的；附上的"],"en":["included with a letter or document"]}', NULL, 'please find enclosed / enclosed herewith', '[{"en":"Please find enclosed a copy of the invoice.","zh-TW":"請查閱附件中的發票副本。"},{"en":"A brochure is enclosed for your reference.","zh-TW":"附上一份宣傳冊供您參考。"}]', '{"verb":"enclose","noun":"enclosure"}', NULL, 3, 1171, 111),
(1172, 'encounter', '/ɪnˈkaʊntər/', 'verb / noun', '{"zh-TW":["遭遇；碰到","遭遇；偶遇"],"en":["to unexpectedly meet or face","to unexpectedly meet or face something"]}', '{"prefix":{"text":"en-","meaning":"in (在)"},"root":{"text":"counter","meaning":"against (對面)"},"logic":"在對面碰上，即「遭遇」。"}', 'encounter difficulties/problems; encounter problems / encounter difficulties', '[{"en":"We encountered several problems during installation.","zh-TW":"我們在安裝過程中遇到了幾個問題。"},{"en":"It was her first encounter with the CEO.","zh-TW":"這是她第一次與執行長碰面。"},{"en":"We encountered several problems along the way.","zh-TW":"我們一路上遇到了幾個問題。"},{"en":"I encountered an old friend at the airport.","zh-TW":"我在機場偶遇一位老朋友。"}]', '{"noun":"encounter","verb":"encounter"}', NULL, 3, 1172, NULL),
(1173, 'encourage', '/ɪnˈkɜːrɪdʒ/', 'verb', '{"zh-TW":["鼓勵；促進"],"en":["to give support or confidence"]}', NULL, 'encourage + 人 + to', '[{"en":"The manager encouraged her team to innovate.","zh-TW":"經理鼓勵她的團隊創新。"},{"en":"Low interest rates encourage borrowing.","zh-TW":"低利率鼓勵借貸。"}]', '{"noun":"encouragement","verb":"encourage","adjective":"encouraging"}', NULL, 3, 1173, 112),
(1174, 'encouragement', 'ɪnˈkɜːrɪdʒmənt', 'noun', '{"zh-TW":["鼓勵；激勵","支持"],"en":["support that motivates action","words that inspire confidence"]}', NULL, 'offer encouragement/positive encouragement', '[{"en":"Her encouragement helped the team succeed.","zh-TW":"她的鼓勵幫助團隊成功。"}]', '{"verb":"encourage","adjective":"encouraging","adverb":"encouragingly"}', NULL, 5, 1174, NULL),
(1175, 'encryption', '/ɪnˈkrɪpʃən/', 'noun', '{"zh-TW":["加密"],"en":["the process of converting data into a secret code"]}', NULL, 'data encryption / end-to-end encryption', '[{"en":"The message uses end-to-end encryption.","zh-TW":"訊息使用端對端加密。"},{"en":"Encryption protects your data.","zh-TW":"加密保護你的資料。"}]', '{"verb":"encrypt","adjective":"encrypted"}', NULL, 4, 1175, NULL),
(1176, 'encumbrance', '/ɪnˈkʌmbrəns/', 'noun', '{"zh-TW":["負擔；抵押債務"],"en":["a claim, lien, or liability attached to an asset or property"]}', NULL, 'check for encumbrances / clear encumbrances', '[{"en":"The property was sold free of all encumbrances.","zh-TW":"房產以無任何負擔的方式出售了。"},{"en":"The title search revealed an outstanding encumbrance on the land.","zh-TW":"產權搜索揭示了土地上的未清償抵押債務。"}]', '{"verb":"encumber","adjective":"encumbered"}', NULL, 4, 1176, NULL),
(1177, 'end', '/ɛnd/', 'noun', '{"zh-TW":["結束；末端"],"en":["the final part","to finish"]}', NULL, 'at the end / end up', '[{"en":"At the end of the month, we review performance.","zh-TW":"月底我們會檢討績效。"},{"en":"The contract ends next year.","zh-TW":"合約明年到期。"}]', '{"noun":"end","verb":"end","adjective":"endless","noun2":"ending"}', NULL, 1, 1177, NULL),
(1178, 'endorse', '/ɪnˈdɔːrs/', 'verb', '{"zh-TW":["背書；認可"],"en":["to publicly approve or support"]}', NULL, 'endorse a product/candidate', '[{"en":"Several celebrities endorsed the brand.","zh-TW":"多位名人為該品牌背書。"},{"en":"The board endorsed the new strategy.","zh-TW":"董事會認可了新策略。"}]', '{"noun":"endorsement","verb":"endorse"}', NULL, 3, 1178, 867),
(1179, 'endorsement', '/ɪnˈdɔːrsmənt/', 'noun', '{"zh-TW":["代言；背書"],"en":["public approval or support given by a prominent person or organization"]}', NULL, 'celebrity endorsement / brand endorsement / endorsement deal', '[{"en":"The athlete''s endorsement boosted product sales by 40%.","zh-TW":"這位運動員的代言使產品銷售額提升了40%。"},{"en":"An official endorsement from an industry body builds credibility.","zh-TW":"行業機構的官方背書建立了可信度。"}]', '{"verb":"endorse","noun":"endorser"}', NULL, 4, 1179, 781),
(1180, 'endowment', '/ɪnˈdaʊmənt/', 'noun', '{"zh-TW":["捐贈基金；捐款"],"en":["a fund or gift made to an institution for a specific purpose"]}', NULL, 'endowment fund / university endowment / establish an endowment', '[{"en":"The university endowment funds research and scholarships.","zh-TW":"大學捐贈基金支持研究和獎學金。"},{"en":"She made a substantial endowment to the hospital foundation.","zh-TW":"她向醫院基金會捐贈了一大筆款項。"}]', '{"verb":"endow"}', NULL, 3, 1180, NULL),
(1181, 'enemy', '/ˈɛnəmi/', 'noun', '{"zh-TW":["敵人；敵方"],"en":["a person who is hostile to another"]}', NULL, 'worst enemy / make enemies', '[{"en":"Procrastination is your worst enemy.","zh-TW":"拖延是你最大的敵人。"},{"en":"Don''t make enemies in the industry.","zh-TW":"別在業界樹敵。"}]', '{"noun":"enemy","noun2":"enmity"}', NULL, 2, 1181, NULL),
(1182, 'energy', 'ˈɛnərdʒi', 'noun', '{"zh-TW":["能量；精力","能源"],"en":["the capacity to do work","enthusiasm and vitality"]}', NULL, 'renewable energy/full of energy', '[{"en":"The company is shifting to renewable energy.","zh-TW":"公司正在轉向可再生能源。"}]', '{"adjective":"energetic","adverb":"energetically"}', NULL, 2, 1182, NULL),
(1183, 'enforce', '/ɪnˈfɔːrs/', 'verb', '{"zh-TW":["執行；強制","執行；強制實施"],"en":["to compel compliance with a law or rule","to make sure a law or rule is obeyed"]}', NULL, 'enforce regulations/rules; enforce the law / strictly enforced', '[{"en":"The police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The contract will be strictly enforced.","zh-TW":"合約將被嚴格執行。"},{"en":"Police enforce traffic laws.","zh-TW":"警察執行交通法規。"},{"en":"The rules are strictly enforced.","zh-TW":"規則被嚴格執行。"}]', '{"noun":"enforcement","verb":"enforce","adjective":"enforceable"}', NULL, 3, 1183, 677),
(1184, 'enforceable', '/ɪnˈfɔːrsəbəl/', 'adjective', '{"zh-TW":["可執行的；有法律效力的"],"en":["legally valid and capable of being enforced by courts"]}', NULL, 'legally enforceable / enforceable contract / make enforceable', '[{"en":"The agreement must be written to be legally enforceable.","zh-TW":"協議必須以書面形式才具有法律執行力。"},{"en":"Not all verbal agreements are enforceable in court.","zh-TW":"並非所有口頭協議都在法庭上具有可執行性。"}]', '{"verb":"enforce","noun":"enforcement"}', NULL, 4, 1184, NULL),
(1185, 'engage', '/ɪnˈɡeɪdʒ/', 'verb', '{"zh-TW":["【主要意義-動詞】吸引（注意力）；使參與","【次要意義-動詞】雇用；聘請（正式）","【次要意義-動詞】（齒輪/機器）嚙合；接合","【次要意義-動詞】與……交涉；與……接觸"],"en":["[primary] to attract and keep attention; to involve someone","[secondary] to hire or employ someone for a specific purpose","[secondary] to connect mechanical parts together; to put into gear","[secondary] to enter into discussion or conflict with someone"]}', '{"prefix":{"text":"en-","meaning":"in (進入)"},"root":{"text":"gage","meaning":"pledge (承諾)"},"logic":"進入承諾參與，即「參與」。"}', 'engage a consultant / engage with stakeholders / engage the clutch / fully engaged', '[{"en":"The company engaged a top law firm to handle the acquisition.","zh-TW":"公司聘請了一家頂級律師事務所來處理此次收購。"},{"en":"Management must engage with employees to address the low morale issue.","zh-TW":"管理層必須與員工進行溝通，以解決士氣低落的問題。"},{"en":"The new campaign effectively engages customers through interactive content.","zh-TW":"新活動通過互動內容有效地吸引了客戶。"}]', '{"noun":"engagement","adjective":"engaging"}', '動詞 engage = 「聘請」（engage a consultant = 聘請顧問）是正式書面英語用法，engage with（與……接觸/溝通）是 TOEIC 商業和管理文章的高頻表達，考生常誤以為只有「吸引注意力」的意思。', 2, 1185, 346),
(1186, 'engaged', 'ɪnˈɡeɪdʒd', 'adjective', '{"zh-TW":["投入的；積極的","參與的"],"en":["busy with or involved in","committed to work"]}', NULL, 'highly engaged/employee engaged', '[{"en":"Engaged employees are more productive.","zh-TW":"積極投入的員工更有生產力。"}]', '{"verb":"engage","noun":"engagement"}', NULL, 3, 1186, NULL),
(1187, 'engagement', '/ɪnˈɡeɪdʒmənt/', 'noun', '{"zh-TW":["互動；參與度"],"en":["interactions such as likes, comments, shares, and clicks on content"]}', NULL, 'social media engagement / engagement rate / increase engagement', '[{"en":"High engagement on the post signaled strong audience interest.","zh-TW":"貼文上的高互動率表明了強烈的受眾興趣。"},{"en":"Video content typically drives higher engagement than static images.","zh-TW":"視頻內容通常比靜態圖片產生更高的互動率。"}]', '{"verb":"engage","adjective":"engaging"}', NULL, 4, 1187, 557),
(1188, 'engine', '/ˈɛndʒɪn/', 'noun', '{"zh-TW":["引擎；發動機"],"en":["a machine that converts energy into motion"]}', NULL, 'search engine / engine of growth', '[{"en":"Use a search engine to find information.","zh-TW":"使用搜尋引擎查找資訊。"},{"en":"Technology is the engine of growth.","zh-TW":"科技是成長的引擎。"}]', '{"noun":"engine","noun2":"engineer","noun3":"engineering"}', NULL, 2, 1188, NULL),
(1189, 'enhance', '/ɪnˈhæns/', 'verb', '{"zh-TW":["增強；提高","增強；提升"],"en":["to improve the quality or value of","to improve the quality or value of something"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"hance","meaning":"high (高)"},"logic":"使其提高，即「增強」。"}', 'enhance performance/productivity; enhance performance / enhance quality / enhance the experience', '[{"en":"The update will enhance system performance.","zh-TW":"更新將增強系統性能。"},{"en":"Training enhances employee productivity.","zh-TW":"培訓提高員工生產力。"},{"en":"This software enhances image quality.","zh-TW":"這個軟體增強了影像品質。"},{"en":"The new features enhance the user experience.","zh-TW":"新功能提升了使用者體驗。"}]', '{"noun":"enhancement","verb":"enhance"}', NULL, 3, 1189, 113),
(1190, 'enhancement', 'ɪnˈhɑːnsmənt', 'noun', '{"zh-TW":["增強；改善","提升"],"en":["an improvement","making better"]}', NULL, 'product enhancement/service enhancement', '[{"en":"The software update includes several enhancements.","zh-TW":"軟體更新包含幾項改進。"}]', '{"verb":"enhance","adjective":"enhanced"}', NULL, 4, 1190, 558),
(1191, 'enjoy', '/ɪnˈdʒɔɪ/', 'verb', '{"zh-TW":["享受；喜歡"],"en":["to get pleasure from something"]}', NULL, 'enjoy doing / enjoy the benefits', '[{"en":"I enjoy working with this team.","zh-TW":"我喜歡和這個團隊一起工作。"},{"en":"Members enjoy special benefits.","zh-TW":"會員享有特殊福利。"}]', '{"verb":"enjoy","noun":"enjoyment","adjective":"enjoyable"}', NULL, 2, 1191, NULL),
(1192, 'enormous', '/ɪˈnɔːrməs/', 'adjective', '{"zh-TW":["巨大的"],"en":["very large in size, quantity, or extent","very large in size or quantity"]}', '{"prefix":{"text":"e-","meaning":"out (超出)"},"root":{"text":"norm","meaning":"rule/standard (標準)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"超出正常標準的，即「巨大的」。"}', 'enormous amount/potential; enormous amount / enormous pressure / enormous success', '[{"en":"The project requires an enormous investment.","zh-TW":"該項目需要巨額投資。"},{"en":"There is enormous potential for growth.","zh-TW":"有巨大的增長潛力。"},{"en":"The project requires an enormous amount of work.","zh-TW":"這個專案需要大量的工作。"},{"en":"The concert was an enormous success.","zh-TW":"音樂會獲得了巨大的成功。"}]', '{"adjective":"enormous","adverb":"enormously"}', NULL, 3, 1192, NULL),
(1193, 'enough', '/ɪˈnʌf/', 'adjective', '{"zh-TW":["足夠的"],"en":["as much as is needed"]}', NULL, 'good enough / not enough', '[{"en":"We don''t have enough staff for this project.","zh-TW":"我們沒有足夠的人手做這個專案。"},{"en":"Is this good enough?","zh-TW":"這樣夠好嗎？"}]', '{"adjective":"enough","adverb":"enough"}', NULL, 2, 1193, NULL),
(1194, 'enroll', '/ɪnˈroʊl/', 'verb', '{"zh-TW":["註冊；登記","註冊；入學"],"en":["to officially register for a course or program","to officially join a course or school"]}', NULL, 'enroll in a course/program; enroll in / enrollment period', '[{"en":"Over 500 students enrolled in the program.","zh-TW":"超過500名學生註冊了該計畫。"},{"en":"You can enroll online.","zh-TW":"你可以在線上註冊。"},{"en":"She enrolled in a language course.","zh-TW":"她報名了一門語言課程。"},{"en":"Over 500 students enrolled this year.","zh-TW":"今年有超過500名學生入學。"}]', '{"noun":"enrollment","verb":"enroll"}', NULL, 2, 1194, NULL),
(1195, 'enrollment', '/ɪnˈrəʊlmənt/', 'noun', '{"zh-TW":["入學；註冊"],"en":["the act of registering for a course or school"]}', NULL, 'enrollment period / course enrollment', '[{"en":"Enrollment for the spring semester begins in January.","zh-TW":"春季學期的入學從一月開始。"},{"en":"The school saw a 10% increase in enrollment this year.","zh-TW":"學校今年的入學人數增加了10%。"}]', '{"verb":"enroll","adjective":"enrolled"}', NULL, 4, 1195, 347),
(1196, 'ensure', '/ɪnˈʃʊr/', 'verb', '{"zh-TW":["確保"],"en":["to make certain that something happens"]}', '{"prefix":{"text":"en-","meaning":"make (使)"},"root":{"text":"sure","meaning":"sure (確定)"},"logic":"使其確定，即「確保」。"}', 'ensure quality/safety; ensure quality / ensure safety / ensure that', '[{"en":"Please ensure all data is backed up.","zh-TW":"請確保所有資料都已備份。"},{"en":"We must ensure customer satisfaction.","zh-TW":"我們必須確保客戶滿意度。"},{"en":"Please ensure all doors are locked.","zh-TW":"請確保所有門都已上鎖。"},{"en":"We must ensure the safety of our employees.","zh-TW":"我們必須確保員工的安全。"}]', '{"verb":"ensure"}', NULL, 2, 1196, 114),
(1197, 'enter', '/ˈɛntər/', 'verb', '{"zh-TW":["進入；輸入"],"en":["to go into a place","to type data"]}', NULL, 'enter the market / enter data', '[{"en":"They plan to enter the Asian market.","zh-TW":"他們計畫進入亞洲市場。"},{"en":"Please enter your password.","zh-TW":"請輸入你的密碼。"}]', '{"verb":"enter","noun":"entrance","noun2":"entry"}', NULL, 2, 1197, NULL),
(1198, 'enterprise', '/ˈentərpraɪz/', 'noun', '{"zh-TW":["企業；事業"],"en":["a business or company; a bold undertaking"]}', NULL, 'private/state enterprise', '[{"en":"Small enterprises drive economic growth.","zh-TW":"小型企業推動經濟增長。"},{"en":"The new enterprise launched last quarter.","zh-TW":"新企業上季度啟動了。"}]', '{"noun":"enterprise","adjective":"enterprising"}', NULL, 4, 1198, 348),
(1199, 'entertainment', '/ˌɛntərˈteɪnmənt/', 'noun', '{"zh-TW":["娛樂"],"en":["activities for enjoyment"]}', NULL, 'entertainment industry / live entertainment', '[{"en":"The hotel offers nightly entertainment.","zh-TW":"飯店每晚提供娛樂節目。"},{"en":"The entertainment industry is growing.","zh-TW":"娛樂產業正在成長。"}]', '{"verb":"entertain","noun2":"entertainer","adjective":"entertaining"}', NULL, 5, 1199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1200, 'enthusiastic', '/ɪnˌθjuːziˈæstɪk/', 'adjective', '{"zh-TW":["熱情的；熱心的"],"en":["showing intense enjoyment or interest"]}', '{"prefix":{"text":"en-","meaning":"in (在內)"},"root":{"text":"thusi","meaning":"god (神)"},"suffix":{"text":"-astic","meaning":"relating to (相關的)"},"logic":"如同有神靈附體般的熱情。"}', 'enthusiastic about / enthusiastic response', '[{"en":"She is enthusiastic about her new job.","zh-TW":"她對新工作充滿熱情。"},{"en":"The audience gave an enthusiastic response.","zh-TW":"觀眾給予熱烈回應。"}]', '{"noun":"enthusiasm","adverb":"enthusiastically"}', NULL, 4, 1200, NULL),
(1201, 'entire', '/ɪnˈtaɪər/', 'adjective', '{"zh-TW":["整個的；全部的"],"en":["whole; complete","with no part left out; whole"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"tire","meaning":"touch/diminish (觸及/削減)"},"logic":"未被削減的，即「完整的」。"}', 'the entire team/process; the entire team / the entire day / in its entirety', '[{"en":"The entire team was present at the meeting.","zh-TW":"整個團隊都出席了會議。"},{"en":"She spent the entire day on the report.","zh-TW":"她花了一整天在報告上。"},{"en":"The entire team worked overtime.","zh-TW":"整個團隊加班工作。"},{"en":"She read the entire book in one day.","zh-TW":"她一天內讀完了整本書。"}]', '{"adjective":"entire","adverb":"entirely","noun":"entirety"}', NULL, 2, 1201, 115),
(1202, 'entitle', '/ɪnˈtaɪtəl/', 'verb', '{"zh-TW":["賦予權利；命名"],"en":["to give someone the right to do something"]}', NULL, 'be entitled to', '[{"en":"Full-time staff are entitled to 20 days of leave.","zh-TW":"全職員工有權享有20天假期。"},{"en":"The book is entitled ''Modern Management''.","zh-TW":"這本書名為《現代管理》。"}]', '{"noun":"entitlement","verb":"entitle","adjective":"entitled"}', NULL, 3, 1202, NULL),
(1203, 'entitlement', '/ɪnˈtaɪtəlmənt/', 'noun', '{"zh-TW":["權利；應得福利"],"en":["a benefit that an employee has a right to receive"]}', NULL, 'leave entitlement / statutory entitlement / entitlement to benefits', '[{"en":"All employees have a minimum leave entitlement of 14 days.","zh-TW":"所有員工享有最低14天的假期權利。"},{"en":"She checked her entitlement to overtime pay.","zh-TW":"她查詢了她的加班費權利。"}]', '{"verb":"entitle","adjective":"entitled"}', NULL, 4, 1203, 559),
(1204, 'entree', '/ˈɒntreɪ/', 'noun', '{"zh-TW":["主菜"],"en":["the main dish of a meal"]}', NULL, 'entree selection / order an entree', '[{"en":"The entree includes a choice of fish or beef.","zh-TW":"主菜包含魚或牛肉的選擇。"},{"en":"Each entree is served with seasonal vegetables.","zh-TW":"每道主菜配有時令蔬菜。"}]', NULL, NULL, 2, 1204, NULL),
(1205, 'entrepreneur', '/ˌɑːntrəprəˈnɜːr/', 'noun', '{"zh-TW":["企業家；創業者"],"en":["a person who starts and runs a business"]}', NULL, 'successful entrepreneur', '[{"en":"She is a successful entrepreneur in tech.","zh-TW":"她是科技領域的成功企業家。"},{"en":"Entrepreneurs drive innovation.","zh-TW":"企業家推動創新。"}]', '{"noun":"entrepreneur/entrepreneurship","adjective":"entrepreneurial"}', NULL, 4, 1205, NULL),
(1206, 'enumerate', '/ɪˈnjuːməreɪt/', 'verb', '{"zh-TW":["列舉；逐一說明"],"en":["to list or count things individually"]}', NULL, 'enumerate the benefits / enumerate responsibilities', '[{"en":"The contract enumerates all deliverables and payment milestones.","zh-TW":"合約列舉了所有交付成果和付款里程碑。"},{"en":"Please enumerate the risks identified in the assessment.","zh-TW":"請列舉評估中識別的風險。"}]', '{"noun":"enumeration","adjective":"enumerated"}', NULL, 3, 1206, 679),
(1207, 'environment', '/ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["環境"],"en":["the natural world; surrounding conditions"]}', NULL, 'work/business environment', '[{"en":"We must protect the environment.","zh-TW":"我們必須保護環境。"},{"en":"A positive work environment boosts morale.","zh-TW":"積極的工作環境提升士氣。"}]', '{"noun":"environment/environmentalist","adjective":"environmental","adverb":"environmentally"}', NULL, 4, 1207, 350),
(1208, 'equal', '/ˈiːkwəl/', 'adjective / verb', '{"zh-TW":["相等的；等於"],"en":["the same in quantity, size, or value"]}', NULL, 'equal opportunity/rights', '[{"en":"All employees should receive equal pay for equal work.","zh-TW":"所有員工同工應同酬。"},{"en":"The total equals $5,000.","zh-TW":"總計等於5000美元。"}]', '{"noun":"equality","verb":"equal","adjective":"equal","adverb":"equally"}', NULL, 2, 1208, NULL),
(1209, 'equip', '/ɪˈkwɪp/', 'verb', '{"zh-TW":["裝備；配備"],"en":["to provide with necessary items or skills"]}', NULL, 'well-equipped / equip with', '[{"en":"The office is equipped with modern technology.","zh-TW":"辦公室配備了現代技術。"},{"en":"Training equips employees with new skills.","zh-TW":"培訓為員工配備新技能。"}]', '{"noun":"equipment","verb":"equip","adjective":"equipped"}', NULL, 2, 1209, 680),
(1210, 'equipment', 'ɪˈkwɪpmənt', 'noun', '{"zh-TW":["設備；器材","裝備"],"en":["tools or machines needed","items supplied for a purpose"]}', NULL, 'office equipment/safety equipment', '[{"en":"All equipment must be properly maintained.","zh-TW":"所有設備必須妥善維護。"}]', '{"verb":"equip","adjective":"equipped"}', NULL, 3, 1210, 28),
(1211, 'equity', '/ˈɛkwɪti/', 'noun', '{"zh-TW":["股權；權益"],"en":["the value of shares in a company","fairness"]}', NULL, 'private equity / home equity', '[{"en":"They raised capital through private equity.","zh-TW":"他們透過私募股權募集資金。"},{"en":"The company has strong brand equity.","zh-TW":"公司擁有強大的品牌價值。"}]', '{"noun":"equity","adjective":"equitable"}', NULL, 2, 1211, 351),
(1212, 'equivalent', '/ɪˈkwɪvələnt/', 'adjective / noun', '{"zh-TW":["等同的；等價物","等同的；等價的"],"en":["equal in value, function, or meaning"]}', '{"prefix":{"text":"equi-","meaning":"equal (等同)"},"root":{"text":"val","meaning":"worth (價值)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"價值等同的。"}', 'equivalent to; equivalent to / the equivalent of / roughly equivalent', '[{"en":"One mile is equivalent to 1.6 kilometers.","zh-TW":"一英里等於1.6公里。"},{"en":"There is no equivalent product on the market.","zh-TW":"市場上沒有同等的產品。"},{"en":"One mile is roughly equivalent to 1.6 kilometers.","zh-TW":"一英里大約等於1.6公里。"},{"en":"There is no equivalent word in English.","zh-TW":"英語中沒有等同的字。"}]', '{"noun":"equivalent/equivalence","adjective":"equivalent"}', NULL, 4, 1212, 868),
(1213, 'ergonomics', '/ˌɜːrɡəˈnɒmɪks/', 'noun', '{"zh-TW":["人體工學；人因工程"],"en":["the science of designing workplaces to fit the user"]}', NULL, 'improve ergonomics / ergonomics assessment', '[{"en":"Good ergonomics reduces the risk of repetitive strain injuries.","zh-TW":"良好的人體工學設計降低了重複性損傷的風險。"},{"en":"The company conducted an ergonomics assessment for all workstations.","zh-TW":"公司對所有工作站進行了人體工學評估。"}]', '{"adjective":"ergonomic","adverb":"ergonomically"}', NULL, 4, 1213, NULL),
(1214, 'erode', '/ɪˈroʊd/', 'verb', '{"zh-TW":["侵蝕；削弱"],"en":["to gradually wear away or diminish"]}', NULL, 'erode confidence/trust', '[{"en":"Competition has eroded profit margins.","zh-TW":"競爭侵蝕了利潤率。"},{"en":"Public trust in the brand has eroded.","zh-TW":"公眾對品牌的信任已被削弱。"}]', '{"noun":"erosion","verb":"erode"}', NULL, 2, 1214, NULL),
(1215, 'erosion', '/ɪˈroʊʒn/', 'noun', '{"zh-TW":["侵蝕"],"en":["the gradual wearing away of soil or rock"]}', '{"prefix":{"text":"e-","meaning":"away (離去)"},"root":{"text":"ros","meaning":"gnaw (啃蝕)"},"suffix":{"text":"-ion","meaning":"process (過程)"},"logic":"被啃蝕掉的過程，即「侵蝕」。"}', 'soil erosion / coastal erosion', '[{"en":"Soil erosion is a serious environmental problem.","zh-TW":"土壤侵蝕是嚴重的環境問題。"},{"en":"Heavy rain accelerates erosion.","zh-TW":"大雨加速侵蝕。"}]', '{"verb":"erode"}', NULL, 3, 1215, NULL),
(1216, 'ERP', '/ˌiː ɑːr ˈpiː/', 'noun', '{"zh-TW":["企業資源規劃系統"],"en":["enterprise resource planning; integrated software for managing business processes"]}', NULL, 'implement an ERP / ERP system / ERP software / ERP upgrade', '[{"en":"The company implemented a new ERP to unify its global operations.","zh-TW":"公司實施了新的企業資源規劃系統以統一其全球業務。"},{"en":"ERP integration reduced manual data entry errors significantly.","zh-TW":"ERP整合顯著減少了手動數據輸入錯誤。"}]', '{"full form":"enterprise resource planning"}', NULL, 1, 1216, NULL),
(1217, 'error', '/ˈerər/', 'noun', '{"zh-TW":["錯誤；失誤"],"en":["a mistake; something incorrectly done"]}', NULL, 'human/clerical error', '[{"en":"The report contained several errors.","zh-TW":"報告中有幾處錯誤。"},{"en":"The error was caused by a software bug.","zh-TW":"錯誤是由軟體缺陷造成的。"}]', '{"noun":"error","adjective":"erroneous"}', NULL, 2, 1217, NULL),
(1218, 'escalate', '/ˈeskəleɪt/', 'verb', '{"zh-TW":["上報；升級"],"en":["to refer an issue to a higher authority or increase intensity"]}', NULL, 'escalate a complaint / escalate to management / escalate an issue', '[{"en":"She escalated the unresolved complaint to her supervisor.","zh-TW":"她將未解決的投訴上報給主管。"},{"en":"If a solution cannot be found, escalate the issue immediately.","zh-TW":"如果找不到解決方案，立即上報問題。"}]', '{"noun":"escalation","adjective":"escalated"}', NULL, 3, 1218, 681),
(1219, 'escalation', '/ˌeskəˈleɪʃən/', 'noun', '{"zh-TW":["升級；上報"],"en":["raising an issue to a higher authority when it cannot be resolved at the current level"]}', NULL, 'escalation process / escalate an issue / escalation path', '[{"en":"The customer complaint required escalation to the director.","zh-TW":"客戶投訴需要上報給總監。"},{"en":"Clear escalation paths reduce delays in problem resolution.","zh-TW":"清晰的升級路徑減少了問題解決的延誤。"}]', '{"verb":"escalate","adjective":"escalated"}', NULL, 4, 1219, 784),
(1220, 'escape', '/ɪˈskeɪp/', 'verb', '{"zh-TW":["逃脫；避免"],"en":["to get free from","to avoid something unpleasant"]}', NULL, 'escape route / narrow escape', '[{"en":"Know the escape routes in case of fire.","zh-TW":"了解火災時的逃生路線。"},{"en":"We had a narrow escape from the flooding.","zh-TW":"我們險些遭遇洪水。"}]', '{"verb":"escape","noun":"escape"}', NULL, 2, 1220, NULL),
(1221, 'escrow', '/ˈeskroʊ/', 'noun', '{"zh-TW":["第三方託管；代管"],"en":["a financial arrangement where a third party holds assets until conditions are met"]}', NULL, 'hold in escrow / escrow account / place funds in escrow / release from escrow', '[{"en":"Funds were placed in escrow pending completion of the sale.","zh-TW":"資金被放入第三方託管，等待銷售完成。"},{"en":"The escrow agent released payment once all conditions were satisfied.","zh-TW":"所有條件滿足後，代管代理人釋放了付款。"}]', '{"verb":"escrow"}', NULL, 2, 1221, NULL),
(1222, 'ESOP', '/ˈiːsɒp/', 'noun', '{"zh-TW":["員工持股計劃"],"en":["employee stock ownership plan; a benefit giving employees company shares"]}', NULL, 'set up an ESOP / ESOP contribution / ESOP plan', '[{"en":"The ESOP aligned employees'' interests with the company''s success.","zh-TW":"員工持股計劃使員工利益與公司成功保持一致。"},{"en":"Many tech firms use ESOPs as a long-term retention tool.","zh-TW":"許多科技公司使用員工持股計劃作為長期留才工具。"}]', '{"full form":"employee stock ownership plan"}', NULL, 1, 1222, NULL),
(1223, 'espresso', '/ɪˈsprɛsəʊ/', 'noun', '{"zh-TW":["義式濃縮咖啡"],"en":["a strong coffee made by forcing steam through ground coffee"]}', NULL, 'double espresso / espresso shot', '[{"en":"She ordered a double espresso to start her morning.","zh-TW":"她點了一杯雙份義式濃縮咖啡開始她的早晨。"},{"en":"Espresso is the base for many coffee drinks.","zh-TW":"義式濃縮咖啡是許多咖啡飲品的基底。"}]', NULL, NULL, 3, 1223, NULL),
(1224, 'essential', '/ɪˈsenʃəl/', 'adjective', '{"zh-TW":["必要的；基本的","必要的；本質的"],"en":["absolutely necessary; extremely important"]}', '{"root":{"text":"essent","meaning":"being/existence (存在)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與存在本質相關的（不可缺少的）。"}', 'essential for/to; essential skills / essential information / absolutely essential', '[{"en":"Communication skills are essential for this role.","zh-TW":"溝通技能對這個職位是必要的。"},{"en":"It is essential to meet the deadline.","zh-TW":"在截止日期前完成是必要的。"},{"en":"Water is essential for life.","zh-TW":"水是生命所必需的。"},{"en":"Good communication skills are essential for this job.","zh-TW":"良好的溝通能力對這份工作至關重要。"}]', '{"noun":"essential/essentials","adjective":"essential","adverb":"essentially"}', NULL, 3, 1224, 869),
(1225, 'establish', '/ɪˈstæblɪʃ/', 'verb', '{"zh-TW":["建立；確立","建立；設立"],"en":["to set up; to prove or show","to set up on a firm or permanent basis"]}', '{"prefix":{"text":"e-","meaning":"out (完全)"},"root":{"text":"stabl","meaning":"stable (穩定)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使其穩固確立，即「建立」。"}', 'establish a company/reputation; establish a company / well-established', '[{"en":"The company was established in 1990.","zh-TW":"公司成立於1990年。"},{"en":"We need to establish clear guidelines.","zh-TW":"我們需要建立明確的指導方針。"},{"en":"They established a new policy for remote work.","zh-TW":"他們制定了新的遠端工作政策。"}]', '{"noun":"establishment","verb":"establish","adjective":"established"}', NULL, 3, 1225, 116),
(1226, 'estimate', '/ˈestɪmeɪt/', 'verb / noun', '{"zh-TW":["估計；預算","估計"],"en":["to roughly calculate; an approximate judgment","to roughly calculate or judge the value of"]}', '{"root":{"text":"estim","meaning":"value (評價)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"做出評價，即「估計」。"}', 'rough/conservative estimate; rough estimate / cost estimate / estimate the cost', '[{"en":"We estimate the cost at $50,000.","zh-TW":"我們估計成本為5萬美元。"},{"en":"The initial estimate was too low.","zh-TW":"最初的估計太低了。"},{"en":"We estimate the project will cost $2 million.","zh-TW":"我們估計這個專案將花費200萬美元。"},{"en":"Can you give me a rough estimate?","zh-TW":"你能給我一個粗略的估計嗎？"}]', '{"noun":"estimate/estimation","verb":"estimate","adjective":"estimated","noun2":"estimation"}', NULL, 3, 1226, 29),
(1227, 'estimation', 'ˌɛstɪˈmeɪʃən', 'noun', '{"zh-TW":["估算；估計","評價"],"en":["a calculated guess","a judgment of value"]}', NULL, 'cost estimation/time estimation', '[{"en":"Please prepare an accurate cost estimation.","zh-TW":"請準備準確的成本估算。"}]', '{"verb":"estimate","adjective":"estimated"}', NULL, 4, 1227, 785),
(1228, 'evaluate', '/ɪˈvæljueɪt/', 'verb', '{"zh-TW":["評估；評價","評估"],"en":["to judge the value or quality of","to judge or determine the significance or value of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"valu","meaning":"value (價值)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"衡量出價值來，即「評估」。"}', 'evaluate performance/options; evaluate performance / evaluate options', '[{"en":"We need to evaluate all options carefully.","zh-TW":"我們需要仔細評估所有選項。"},{"en":"Employee performance is evaluated annually.","zh-TW":"員工績效每年評估一次。"},{"en":"Teachers evaluate student performance regularly.","zh-TW":"老師定期評估學生表現。"},{"en":"We need to evaluate all the options.","zh-TW":"我們需要評估所有選項。"}]', '{"noun":"evaluation","verb":"evaluate"}', NULL, 3, 1228, 30),
(1229, 'evaluation', 'ɪˌvæljʊˈeɪʃən', 'noun', '{"zh-TW":["評估；評價","考核"],"en":["the process of assessing","a judgment of value"]}', NULL, 'performance evaluation/project evaluation', '[{"en":"The evaluation report was submitted.","zh-TW":"評估報告已提交。"}]', '{"verb":"evaluate","adjective":"evaluative"}', NULL, 4, 1229, 561),
(1230, 'even', '/ˈiːvən/', 'verb, adjective, adverb', '{"zh-TW":["【主要意義-副詞/連接詞】甚至；連……也","【次要意義-動詞】使平整；使相等；使均衡","【次要意義-形容詞】平穩的；均等的；偶數的"],"en":["[primary] used to emphasize something unexpected","[secondary - verb] to make flat, level, or equal","[secondary - adjective] equal, level, or divisible by two"]}', NULL, 'even out / even up / even the score / on an even keel', '[{"en":"The extra payment will even out the discrepancy in the accounts.","zh-TW":"額外付款將消除帳目中的差異。"},{"en":"They worked to even the playing field for smaller companies.","zh-TW":"他們努力為小公司創造公平競爭的環境。"},{"en":"Production levels have evened out after the initial surge.","zh-TW":"初期激增後，生產水平已趨於平穩。"}]', '{"adverb":"evenly","noun":"evenness"}', '動詞 even out/up 意為「使平衡/消除差異」，常見於 TOEIC 財務或生產排程的語境，與副詞「甚至」的用法完全不同。', 1, 1230, NULL),
(1231, 'evening', '/ˈiːvnɪŋ/', 'noun', '{"zh-TW":["傍晚；晚上"],"en":["the part of the day between afternoon and night"]}', NULL, 'good evening / evening shift', '[{"en":"Good evening, everyone.","zh-TW":"大家晚上好。"},{"en":"She works the evening shift.","zh-TW":"她上晚班。"}]', '{"noun":"evening"}', NULL, 3, 1231, NULL),
(1232, 'event', 'ɪˈvɛnt', 'noun', '{"zh-TW":["事件；活動","賽事"],"en":["a thing that happens","a planned occasion"]}', NULL, 'corporate event/upcoming event', '[{"en":"The annual event is scheduled for May.","zh-TW":"年度活動定於五月舉行。"}]', '{"adjective":"eventful","adverb":"eventfully"}', NULL, 2, 1232, NULL),
(1233, 'eventually', '/ɪˈventʃuəli/', 'adverb', '{"zh-TW":["最終；終於"],"en":["in the end; after a period of time"]}', NULL, 'eventually lead to', '[{"en":"The negotiations eventually led to an agreement.","zh-TW":"談判最終達成了協議。"},{"en":"He eventually became the CEO.","zh-TW":"他最終成為了執行長。"}]', '{"adjective":"eventual","adverb":"eventually"}', NULL, 4, 1233, NULL),
(1234, 'evidence', '/ˈevɪdəns/', 'noun', '{"zh-TW":["證據；跡象","證據"],"en":["facts or signs showing something is true","facts or information indicating whether something is true"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"vid","meaning":"see (看)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"看得出來的事實，即「證據」。"}', 'provide/present evidence; scientific evidence / evidence suggests / lack of evidence', '[{"en":"There is evidence of improvement in sales.","zh-TW":"有銷售改善的證據。"},{"en":"The data provides evidence of a trend.","zh-TW":"數據提供了趨勢的證據。"},{"en":"There is no evidence to support this claim.","zh-TW":"沒有證據支持這項說法。"},{"en":"The evidence suggests a link between the two.","zh-TW":"證據顯示兩者之間有關聯。"}]', '{"noun":"evidence","adjective":"evident","adverb":"evidently"}', NULL, 3, 1234, 562),
(1235, 'evolve', '/ɪˈvɑːlv/', 'verb', '{"zh-TW":["進化；發展"],"en":["to develop gradually over time"]}', NULL, 'evolve into/over time', '[{"en":"The company has evolved into a global brand.","zh-TW":"公司已發展成為全球品牌。"},{"en":"Consumer preferences evolve constantly.","zh-TW":"消費者偏好不斷演變。"}]', '{"noun":"evolution","verb":"evolve"}', NULL, 2, 1235, NULL),
(1236, 'exact', '/ɪɡˈzækt/', 'adjective', '{"zh-TW":["精確的；確切的"],"en":["completely accurate; precise"]}', NULL, 'exact amount/location', '[{"en":"The exact cost has not been determined yet.","zh-TW":"確切費用尚未確定。"},{"en":"Please provide the exact date.","zh-TW":"請提供確切日期。"}]', '{"adjective":"exact","adverb":"exactly"}', NULL, 2, 1236, NULL),
(1237, 'exam', '/ɪɡˈzæm/', 'noun', '{"zh-TW":["考試"],"en":["a formal test of knowledge"]}', NULL, 'take an exam / pass an exam', '[{"en":"I have three exams next week.","zh-TW":"我下週有三場考試。"},{"en":"She passed all her exams.","zh-TW":"她通過了所有考試。"}]', '{"noun2":"examination","noun3":"examiner"}', NULL, 1, 1237, NULL),
(1238, 'examination', '/ɪɡˌzæmɪˈneɪʃən/', 'noun', '{"zh-TW":["檢查；診察"],"en":["a formal medical check of someone''s health"]}', NULL, 'physical examination / eye examination', '[{"en":"The doctor performed a thorough physical examination.","zh-TW":"醫生進行了徹底的身體檢查。"},{"en":"An eye examination is recommended every two years.","zh-TW":"建議每兩年進行一次眼科檢查。"}]', '{"verb":"examine","adjective":"examined"}', NULL, 4, 1238, 563),
(1239, 'examine', '/ɪɡˈzæmɪn/', 'verb', '{"zh-TW":["檢查；審查"],"en":["to inspect closely; to test knowledge"]}', NULL, 'examine closely/carefully', '[{"en":"The auditor examined the financial records.","zh-TW":"審計師審查了財務記錄。"},{"en":"We need to examine this issue more closely.","zh-TW":"我們需要更仔細地審查這個問題。"}]', '{"noun":"examination/examiner","verb":"examine"}', NULL, 3, 1239, 352),
(1240, 'example', '/ɪɡˈzæmpəl/', 'noun', '{"zh-TW":["例子；範例"],"en":["something typical of a group","a model to follow"]}', NULL, 'for example / set an example', '[{"en":"For example, we could reduce costs here.","zh-TW":"例如，我們可以在這裡降低成本。"},{"en":"She sets a good example for new staff.","zh-TW":"她為新員工樹立了好榜樣。"}]', '{"noun":"example","adjective":"exemplary","verb":"exemplify"}', NULL, 3, 1240, NULL),
(1241, 'exceed', '/ɪkˈsiːd/', 'verb', '{"zh-TW":["超過；超出","超過；超越"],"en":["to go beyond a limit or expectation","to go beyond a limit or standard"]}', '{"prefix":{"text":"ex-","meaning":"out (超出)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"走出去超越界限，即「超過」。"}', 'exceed expectations/limits; exceed expectations / exceed the limit', '[{"en":"Sales exceeded expectations this quarter.","zh-TW":"本季度銷售超出了預期。"},{"en":"Do not exceed the speed limit.","zh-TW":"不要超過速限。"},{"en":"Sales exceeded our expectations.","zh-TW":"銷售額超出了我們的預期。"}]', '{"adjective":"exceeding","adverb":"exceedingly"}', NULL, 2, 1241, 117),
(1242, 'excellent', '/ˈeksələnt/', 'adjective', '{"zh-TW":["優秀的；極好的"],"en":["extremely good; outstanding"]}', NULL, 'excellent performance/service', '[{"en":"She received excellent feedback from clients.","zh-TW":"她收到了客戶的優秀評價。"},{"en":"The hotel provides excellent service.","zh-TW":"這家飯店提供優質服務。"}]', '{"noun":"excellence","adjective":"excellent"}', NULL, 3, 1242, NULL),
(1243, 'exception', '/ɪkˈsepʃən/', 'noun', '{"zh-TW":["例外"],"en":["something that does not follow a rule"]}', NULL, 'with the exception of / make an exception', '[{"en":"All staff must attend, with no exceptions.","zh-TW":"所有員工必須參加，沒有例外。"},{"en":"We can make an exception in this case.","zh-TW":"在這種情況下我們可以破例。"}]', '{"noun":"exception","adjective":"exceptional","adverb":"exceptionally"}', NULL, 3, 1243, NULL),
(1244, 'excess', '/ɪkˈses/', 'noun / adjective', '{"zh-TW":["過量；多餘的"],"en":["more than necessary or permitted"]}', NULL, 'in excess of / excess baggage', '[{"en":"Costs were in excess of the budget.","zh-TW":"費用超過了預算。"},{"en":"Excess inventory should be sold at a discount.","zh-TW":"多餘的庫存應打折出售。"}]', '{"noun":"excess","adjective":"excessive","adverb":"excessively"}', NULL, 2, 1244, NULL),
(1245, 'exchange', '/ɪksˈtʃeɪndʒ/', 'noun / verb', '{"zh-TW":["交換；兌換"],"en":["to give and receive; a place for trading","to give something and receive something in return"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"change","meaning":"change (改變)"},"logic":"把東西拿出來改變，即「交換」。"}', 'exchange rate / in exchange for; exchange rate / exchange information', '[{"en":"What is today''s exchange rate?","zh-TW":"今天的匯率是多少？"},{"en":"They exchanged business cards at the conference.","zh-TW":"他們在會議上交換了名片。"},{"en":"Can I exchange this shirt for a larger size?","zh-TW":"我可以把這件襯衫換大一號嗎？"},{"en":"They exchanged contact information.","zh-TW":"他們交換了聯絡資訊。"}]', '{"noun":"exchange","verb":"exchange","adjective":"exchangeable"}', NULL, 3, 1245, NULL),
(1246, 'excited', '/ɪkˈsaɪtɪd/', 'adjective', '{"zh-TW":["興奮的；激動的"],"en":["feeling great enthusiasm"]}', NULL, 'get excited / excited about', '[{"en":"We are excited about the new product launch.","zh-TW":"我們對新產品上市感到興奮。"},{"en":"The team is excited to start.","zh-TW":"團隊很期待開始。"}]', '{"adjective":"excited","verb":"excite","noun":"excitement","adjective2":"exciting"}', NULL, 3, 1246, NULL),
(1247, 'exciting', 'ɪkˈsaɪtɪŋ', 'adjective', '{"zh-TW":["令人興奮的；刺激的","有趣的"],"en":["causing enthusiasm","stimulating"]}', NULL, 'exciting opportunity/exciting news', '[{"en":"This is an exciting opportunity for the company.","zh-TW":"這是公司的一個令人興奮的機會。"}]', '{"verb":"excite","noun":"excitement","adverb":"excitingly"}', NULL, 3, 1247, NULL),
(1248, 'exclude', '/ɪkˈskluːd/', 'verb', '{"zh-TW":["排除；排斥"],"en":["to prevent from being included"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"關在外面，即「排除」。"}', 'exclude from; exclude from / exclude the possibility', '[{"en":"Tax is excluded from the listed price.","zh-TW":"標示價格不含稅。"},{"en":"Some items are excluded from the warranty.","zh-TW":"某些物品不在保固範圍內。"},{"en":"The price excludes tax and delivery.","zh-TW":"價格不含稅和運費。"},{"en":"Don''t exclude anyone from the discussion.","zh-TW":"不要把任何人排除在討論之外。"}]', '{"noun":"exclusion","verb":"exclude","adjective":"exclusive"}', NULL, 3, 1248, NULL),
(1249, 'exclusive', '/ɪkˈskluːsɪv/', 'adjective', '{"zh-TW":["獨家的；專屬的"],"en":["limited to one person or group; high-end"]}', NULL, 'exclusive deal/rights', '[{"en":"We signed an exclusive distribution agreement.","zh-TW":"我們簽署了獨家經銷協議。"},{"en":"The hotel caters to an exclusive clientele.","zh-TW":"這家飯店專門服務高端客戶。"}]', '{"noun":"exclusivity","adjective":"exclusive","adverb":"exclusively"}', NULL, 3, 1249, 353);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1250, 'excursion', '/ɪkˈskɜːrʒən/', 'noun', '{"zh-TW":["短途旅遊；遠足"],"en":["a short trip made for pleasure"]}', NULL, 'day excursion / optional excursion', '[{"en":"We booked an excursion to the nearby volcano.","zh-TW":"我們預訂了前往附近火山的一日遊。"},{"en":"The cruise offers several excursions at each port.","zh-TW":"郵輪在每個港口提供多種短途遊覽。"}]', NULL, NULL, 3, 1250, NULL),
(1251, 'execute', '/ˈeksɪkjuːt/', 'verb', '{"zh-TW":["執行；實施"],"en":["to carry out a plan or action"]}', NULL, 'execute a plan/strategy', '[{"en":"The team executed the project flawlessly.","zh-TW":"團隊完美地執行了項目。"},{"en":"The strategy was well executed.","zh-TW":"該策略執行得很好。"}]', '{"noun":"execution/executive","verb":"execute"}', NULL, 3, 1251, 354),
(1252, 'executive', '/ɪɡˈzekjʊtɪv/', 'noun', '{"zh-TW":["高管；主管"],"en":["a senior manager with significant decision-making authority"]}', NULL, 'senior executive / top executive / executive team / executive decision', '[{"en":"The executive team approved the new strategic direction.","zh-TW":"高管團隊批准了新的戰略方向。"},{"en":"She joined as a senior executive responsible for global sales.","zh-TW":"她以負責全球銷售的高管身份加入。"}]', '{"plural":"executives","adjective":"executive"}', NULL, 3, 1252, 118),
(1253, 'exempt', '/ɪɡˈzempt/', 'adjective / verb', '{"zh-TW":["免除的；豁免"],"en":["free from an obligation or liability"]}', NULL, 'exempt from tax/duty', '[{"en":"Non-profit organizations are exempt from taxes.","zh-TW":"非營利組織免稅。"},{"en":"Small businesses may be exempted from the regulation.","zh-TW":"小型企業可能免於遵守該法規。"}]', '{"noun":"exemption","verb":"exempt","adjective":"exempt"}', NULL, 2, 1253, NULL),
(1254, 'exercise', '/ˈeksərsaɪz/', 'noun / verb', '{"zh-TW":["運動；行使"],"en":["physical activity; to use a right or power"]}', NULL, 'exercise caution/authority', '[{"en":"Please exercise caution when handling chemicals.","zh-TW":"處理化學品時請小心謹慎。"},{"en":"Shareholders may exercise their voting rights.","zh-TW":"股東可以行使投票權。"}]', '{"noun":"exercise","verb":"exercise"}', NULL, 3, 1254, NULL),
(1255, 'exhaust', '/ɪɡˈzɔːst/', 'verb / noun', '{"zh-TW":["耗盡；排氣"],"en":["to use up completely; waste gases"]}', NULL, 'exhaust all options/resources', '[{"en":"We have exhausted all possible solutions.","zh-TW":"我們已經用盡了所有可能的解決方案。"},{"en":"Vehicle exhaust contributes to air pollution.","zh-TW":"汽車排氣造成空氣污染。"}]', '{"noun":"exhaustion/exhaust","verb":"exhaust","adjective":"exhausting/exhausted/exhaustive"}', NULL, 3, 1255, NULL),
(1256, 'exhibit', '/ɪɡˈzɪbɪt/', 'verb / noun', '{"zh-TW":["展覽；展示","展覽品；展覽"],"en":["to show publicly; a display","an object displayed in a museum","a public display of art or other items"]}', '{"prefix":{"text":"ex-","meaning":"out (外)"},"root":{"text":"hibit","meaning":"hold (持有)"},"logic":"拿出來展示，即「展覽」。"}', 'exhibit at a trade show; art exhibit / exhibit hall / on exhibit', '[{"en":"The company will exhibit at the trade fair.","zh-TW":"公司將在商展上展覽。"},{"en":"The museum has a new exhibit on technology.","zh-TW":"博物館有一個新的科技展覽。"},{"en":"The museum has a new dinosaur exhibit.","zh-TW":"博物館有新的恐龍展覽。"},{"en":"Her paintings are on exhibit at the gallery.","zh-TW":"她的畫作正在畫廊展出。"}]', '{"noun":"exhibit/exhibition/exhibitor","verb":"exhibit"}', NULL, 3, 1256, 119),
(1257, 'exhibition', '/ˌɛksɪˈbɪʃən/', 'noun', '{"zh-TW":["展覽"],"en":["a public display of art or objects"]}', NULL, 'art exhibition / on exhibition', '[{"en":"The exhibition runs until March.","zh-TW":"展覽持續到三月。"},{"en":"We visited an art exhibition.","zh-TW":"我們參觀了一場藝術展覽。"}]', '{"verb":"exhibit","noun2":"exhibit"}', NULL, 4, 1257, NULL),
(1258, 'exist', '/ɪɡˈzɪst/', 'verb', '{"zh-TW":["存在"],"en":["to be real; to have actual being"]}', NULL, 'already exist / cease to exist', '[{"en":"The problem still exists.","zh-TW":"問題仍然存在。"},{"en":"Does a solution already exist?","zh-TW":"已經有解決方案了嗎？"}]', '{"verb":"exist","noun":"existence","adjective":"existing","adjective2":"existent"}', NULL, 2, 1258, NULL),
(1259, 'expand', '/ɪkˈspænd/', 'verb', '{"zh-TW":["擴展；擴大"],"en":["to increase in size, number, or importance"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"pand","meaning":"spread (展開)"},"logic":"向外展開，即「擴展」。"}', 'expand operations/business; expand business / expand into new markets', '[{"en":"The company plans to expand into new markets.","zh-TW":"公司計劃擴展到新市場。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品範圍。"},{"en":"The company plans to expand into Asia.","zh-TW":"公司計畫擴展到亞洲。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品線。"}]', '{"noun":"expansion","verb":"expand"}', NULL, 2, 1259, 120),
(1260, 'expansion', '/ɪkˈspænʃən/', 'noun', '{"zh-TW":["擴張；擴展"],"en":["the process of increasing in size, scope, or reach"]}', NULL, 'market expansion / business expansion / rapid expansion', '[{"en":"The company is planning expansion into Asian markets.","zh-TW":"公司正計劃向亞洲市場擴張。"},{"en":"Expansion into new territories requires careful planning.","zh-TW":"進入新領域需要仔細規劃。"}]', '{"verb":"expand","adjective":"expanded"}', NULL, 3, 1260, 566),
(1261, 'expatriate', '/ˈekspætriət/', 'noun', '{"zh-TW":["外派員工；海外派駐人員"],"en":["an employee working in a country other than their home country"]}', NULL, 'expatriate assignment / expatriate package / manage expatriates', '[{"en":"The company sent several expatriates to manage the new office.","zh-TW":"公司派遣了幾名外派員工管理新辦公室。"},{"en":"Expatriate packages typically include housing and travel allowances.","zh-TW":"外派員工方案通常包括住房和差旅津貼。"}]', '{"abbreviation":"expat","verb":"expatriate"}', NULL, 4, 1261, NULL),
(1262, 'expect', '/ɪkˈspekt/', 'verb', '{"zh-TW":["期望；預期"],"en":["to believe something will happen"]}', NULL, 'expect + to / be expected to', '[{"en":"We expect revenue to increase next year.","zh-TW":"我們預期明年收入會增加。"},{"en":"Employees are expected to follow the dress code.","zh-TW":"員工被期望遵守服裝規定。"}]', '{"noun":"expectation","verb":"expect","adjective":"expected"}', NULL, 2, 1262, NULL),
(1263, 'expedite', '/ˈekspədaɪt/', 'verb', '{"zh-TW":["加快；促進"],"en":["to make a process happen more quickly"]}', NULL, 'expedite the process/delivery', '[{"en":"We can expedite shipping for an extra fee.","zh-TW":"我們可以加收費用加快出貨。"},{"en":"Please expedite the approval process.","zh-TW":"請加快審批流程。"}]', '{"verb":"expedite","adjective":"expedited"}', NULL, 3, 1263, 682),
(1264, 'expenditure', '/ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["支出；開支"],"en":["the action of spending money; an amount spent"]}', NULL, 'capital/government expenditure', '[{"en":"Total expenditure exceeded the budget.","zh-TW":"總支出超過了預算。"},{"en":"Capital expenditure was reduced this year.","zh-TW":"今年資本支出減少了。"}]', '{"noun":"expenditure","verb":"expend"}', NULL, 4, 1264, 568),
(1265, 'expense', '/ɪkˈspens/', 'noun', '{"zh-TW":["費用；開支"],"en":["the cost of something; money spent"]}', NULL, 'at the expense of / business expense', '[{"en":"Travel expenses will be reimbursed.","zh-TW":"差旅費用將報銷。"},{"en":"Profit should not come at the expense of quality.","zh-TW":"利潤不應以犧牲品質為代價。"}]', '{"noun":"expense","adjective":"expensive"}', NULL, 3, 1265, 121),
(1266, 'expensive', 'ɪkˈspɛnsɪv', 'adjective', '{"zh-TW":["昂貴的；高價的","費用高的"],"en":["costing a lot of money","high-priced"]}', NULL, 'expensive product/too expensive', '[{"en":"This software is too expensive for our budget.","zh-TW":"這款軟體對我們的預算來說太貴了。"}]', '{"noun":"expense","adverb":"expensively"}', NULL, 3, 1266, NULL),
(1267, 'experience', '/ɪkˈspɪriəns/', 'noun / verb', '{"zh-TW":["經驗；體驗"],"en":["knowledge gained through involvement; to encounter"]}', NULL, 'work/customer experience', '[{"en":"Do you have experience in project management?","zh-TW":"你有項目管理經驗嗎？"},{"en":"Customers experienced technical difficulties.","zh-TW":"客戶遇到了技術困難。"}]', '{"noun":"experience","verb":"experience","adjective":"experienced"}', NULL, 4, 1267, 122),
(1268, 'experiment', '/ɪkˈsperɪmənt/', 'noun / verb', '{"zh-TW":["實驗；試驗"],"en":["a scientific test; to try something new"]}', NULL, 'conduct an experiment', '[{"en":"The team conducted an experiment to test the theory.","zh-TW":"團隊進行了實驗來測試理論。"},{"en":"We are experimenting with new marketing channels.","zh-TW":"我們正在嘗試新的行銷渠道。"}]', '{"noun":"experiment/experimentation","verb":"experiment","adjective":"experimental"}', NULL, 4, 1268, NULL),
(1269, 'expert', '/ˈekspɜːrt/', 'noun / adjective', '{"zh-TW":["專家；專業的"],"en":["a person with great knowledge in a subject"]}', NULL, 'industry/subject expert', '[{"en":"She is an expert in international trade.","zh-TW":"她是國際貿易專家。"},{"en":"We consulted an expert on tax law.","zh-TW":"我們諮詢了一位稅法專家。"}]', '{"noun":"expert/expertise","adjective":"expert"}', NULL, 2, 1269, NULL),
(1270, 'expertise', 'ˌɛkspɜːrˈtiːz', 'noun', '{"zh-TW":["專業知識；技能","專長"],"en":["expert knowledge","a high level of skill"]}', NULL, 'domain expertise/technical expertise', '[{"en":"Her expertise in finance is valuable.","zh-TW":"她在財務方面的專業知識很有價值。"}]', '{"adjective":"expert","adverb":"expertly"}', NULL, 3, 1270, NULL),
(1271, 'expiration', '/ˌɛkspɪˈreɪʃən/', 'noun', '{"zh-TW":["到期；屆滿"],"en":["the end of the period during which something is valid"]}', NULL, 'contract expiration / expiration date', '[{"en":"The contract is approaching its expiration date.","zh-TW":"合約即將到期。"},{"en":"Renew your license before its expiration.","zh-TW":"請在到期前更新您的執照。"}]', '{"verb":"expire","adjective":"expired"}', NULL, 4, 1271, 356),
(1272, 'expire', '/ɪkˈspaɪər/', 'verb', '{"zh-TW":["到期；過期"],"en":["to come to the end of validity"]}', NULL, 'expire on/contract expires', '[{"en":"Your contract expires at the end of the month.","zh-TW":"你的合約月底到期。"},{"en":"The coupon expired yesterday.","zh-TW":"優惠券昨天過期了。"}]', '{"noun":"expiration/expiry","verb":"expire","adjective":"expired"}', NULL, 2, 1272, NULL),
(1273, 'explain', '/ɪkˈspleɪn/', 'verb', '{"zh-TW":["解釋；說明"],"en":["to make something clear"]}', NULL, 'explain how/why', '[{"en":"Can you explain the procedure?","zh-TW":"你能解釋一下流程嗎？"},{"en":"She explained why the project was delayed.","zh-TW":"她解釋了為什麼項目延遲了。"}]', '{"noun":"explanation","verb":"explain","adjective":"explanatory"}', NULL, 3, 1273, NULL),
(1274, 'explicit', '/ɪkˈsplɪsɪt/', 'adjective', '{"zh-TW":["明確的；清楚的"],"en":["stated clearly and in detail"]}', NULL, 'explicit instructions/consent', '[{"en":"The contract contains explicit terms.","zh-TW":"合約包含明確的條款。"},{"en":"You need explicit permission to proceed.","zh-TW":"你需要明確的許可才能繼續。"}]', '{"adjective":"explicit","adverb":"explicitly"}', NULL, 3, 1274, 683),
(1275, 'exploit', '/ɪkˈsplɔɪt/', 'verb', '{"zh-TW":["利用；開發"],"en":["to make full use of; to use unfairly"]}', NULL, 'exploit resources/opportunities', '[{"en":"We should exploit this market opportunity.","zh-TW":"我們應該利用這個市場機會。"},{"en":"The company exploited cheap labor.","zh-TW":"公司剝削了廉價勞動力。"}]', '{"noun":"exploitation","verb":"exploit"}', NULL, 3, 1275, NULL),
(1276, 'explore', '/ɪkˈsplɔːr/', 'verb', '{"zh-TW":["探索；調查"],"en":["to examine or investigate thoroughly"]}', NULL, 'explore options/possibilities', '[{"en":"Let''s explore all available options.","zh-TW":"讓我們探索所有可用的選項。"},{"en":"The team explored new business models.","zh-TW":"團隊探索了新的商業模式。"}]', '{"noun":"exploration/explorer","verb":"explore","adjective":"exploratory"}', NULL, 3, 1276, NULL),
(1277, 'export', '/ˈekspɔːrt/', 'noun / verb', '{"zh-TW":["出口；輸出"],"en":["to sell goods to another country"]}', NULL, 'export goods/data', '[{"en":"Japan exports electronics worldwide.","zh-TW":"日本向全球出口電子產品。"},{"en":"Exports grew by 8% last year.","zh-TW":"去年出口增長了8%。"}]', '{"noun":"export/exporter","verb":"export"}', NULL, 2, 1277, 357),
(1278, 'expose', '/ɪkˈspoʊz/', 'verb', '{"zh-TW":["暴露；揭發"],"en":["to make visible; to reveal","to make visible or reveal"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放到外面讓人看到，即「暴露」。"}', 'expose to risk/information; expose to / expose the truth', '[{"en":"Workers were exposed to harmful chemicals.","zh-TW":"工人暴露在有害化學品中。"},{"en":"The investigation exposed fraud in the company.","zh-TW":"調查揭發了公司的詐騙行為。"},{"en":"Children should not be exposed to violence.","zh-TW":"兒童不應暴露在暴力之下。"},{"en":"The journalist exposed the corruption scandal.","zh-TW":"記者揭發了貪腐醜聞。"}]', '{"noun":"exposure","verb":"expose","adjective":"exposed"}', NULL, 2, 1278, NULL),
(1279, 'exposure', 'ɪkˈspoʊʒər', 'noun', '{"zh-TW":["曝光；接觸","暴露"],"en":["experience or knowledge gained","public attention"]}', NULL, 'market exposure/brand exposure', '[{"en":"International exposure helps career growth.","zh-TW":"國際接觸有助於職業發展。"}]', '{"verb":"expose","adjective":"exposed"}', NULL, 3, 1279, 570),
(1280, 'extend', '/ɪkˈstend/', 'verb', '{"zh-TW":["延長；擴展","延伸；延長"],"en":["to make longer or larger"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tend","meaning":"stretch (伸展)"},"logic":"向外伸展，即「延伸」。"}', 'extend a deadline/contract; extend a deadline / extend an invitation', '[{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以將截止日期延長一週嗎？"},{"en":"The company extended its operations to Asia.","zh-TW":"公司將業務擴展到亞洲。"},{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以把截止期限延長一週嗎？"},{"en":"The road extends for 200 kilometers.","zh-TW":"這條路延伸了200公里。"}]', '{"noun":"extension","verb":"extend","adjective":"extensive/extended","adjective2":"extended"}', NULL, 2, 1280, 123),
(1281, 'extension', 'ɪkˈstɛnʃən', 'noun', '{"zh-TW":["延期；延長","分機"],"en":["an additional period of time","a telephone number within a system"]}', NULL, 'request an extension/extension number', '[{"en":"Please call extension 204 for support.","zh-TW":"請撥打分機204以獲取支援。"}]', '{"verb":"extend","adjective":"extensible","adverb":"extensively"}', NULL, 3, 1281, 571),
(1282, 'extensive', '/ɪkˈstensɪv/', 'adjective', '{"zh-TW":["廣泛的；大量的"],"en":["covering a large area or having great range","covering a large area or having a wide scope"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tens","meaning":"stretch (伸展)"},"suffix":{"text":"-ive","meaning":"having quality (具有…特質)"},"logic":"具有向外伸展特質的，即「廣泛的」。"}', 'extensive experience/research; extensive research / extensive experience / extensive damage', '[{"en":"She has extensive experience in finance.","zh-TW":"她有豐富的金融經驗。"},{"en":"Extensive research was conducted.","zh-TW":"進行了廣泛的研究。"},{"en":"She has extensive experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"},{"en":"The storm caused extensive damage.","zh-TW":"暴風雨造成了大範圍的損害。"}]', '{"adjective":"extensive","adverb":"extensively","noun":"extent"}', NULL, 3, 1282, 873),
(1283, 'external', '/ɪkˈstɜːrnəl/', 'adjective', '{"zh-TW":["外部的；外在的"],"en":["coming from outside"]}', NULL, 'external factors/audit', '[{"en":"External factors affected the company''s performance.","zh-TW":"外部因素影響了公司的績效。"},{"en":"An external audit will be conducted.","zh-TW":"將進行外部審計。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 3, 1283, 358),
(1284, 'extract', '/ɪkˈstrækt/', 'verb / noun', '{"zh-TW":["提取；摘錄"],"en":["to remove or obtain"]}', NULL, 'extract data/information', '[{"en":"We need to extract data from the system.","zh-TW":"我們需要從系統中提取數據。"},{"en":"The dentist extracted the tooth.","zh-TW":"牙醫拔了那顆牙。"}]', '{"noun":"extract/extraction","verb":"extract"}', NULL, 3, 1284, NULL),
(1285, 'extracurricular', '/ˌɛkstrəkəˈrɪkjʊlər/', 'adjective', '{"zh-TW":["課外的"],"en":["outside the regular academic curriculum"]}', NULL, 'extracurricular activity / extracurricular involvement', '[{"en":"Extracurricular activities help students develop leadership skills.","zh-TW":"課外活動幫助學生培養領導能力。"},{"en":"Colleges value extracurricular involvement in applicants.","zh-TW":"大學重視申請者的課外活動參與。"}]', NULL, NULL, 5, 1285, NULL),
(1286, 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'adjective', '{"zh-TW":["非凡的；特別的"],"en":["very unusual or remarkable"]}', NULL, 'extraordinary achievement/circumstances', '[{"en":"She showed extraordinary leadership.","zh-TW":"她展示了非凡的領導力。"},{"en":"Due to extraordinary circumstances, the event was cancelled.","zh-TW":"由於特殊情況，活動被取消了。"}]', '{"adjective":"extraordinary","adverb":"extraordinarily"}', NULL, 5, 1286, NULL),
(1287, 'eye', '/aɪ/', 'noun', '{"zh-TW":["【主要意義-名詞】眼睛","【次要意義-動詞】注視；盯著看；端詳","【次要意義-名詞】眼力；鑒賞力"],"en":["[primary - noun] the organ of sight","[secondary - verb] to look at someone or something carefully","[secondary - noun] a keen sense of judgment or appreciation"]}', NULL, 'eye someone suspiciously / an eye for detail / keep an eye on / eye-catching', '[{"en":"She eyed the new candidate carefully during the interview.","zh-TW":"她在面試過程中仔細打量這位新候選人。"},{"en":"The manager has a good eye for talent and has recruited several top performers.","zh-TW":"這位經理很有識才的眼力，已招募了幾位頂尖績效員工。"},{"en":"Please keep an eye on the inventory levels and report any shortage.","zh-TW":"請留意庫存水平，並報告任何短缺情況。"}]', '{"adjective":"eye-catching, eagle-eyed"}', '動詞 eye = 「端詳/注視」，片語 have an eye for（對……有眼光）、keep an eye on（留意/監視）、eye-catching（引人注目的）均是 TOEIC 職場描述常見用法。', 1, 1287, NULL),
(1288, 'fabricate', '/ˈfæbrɪkeɪt/', 'verb', '{"zh-TW":["捏造；製造"],"en":["to invent false information; to construct"]}', NULL, 'fabricate evidence/a story', '[{"en":"He was accused of fabricating evidence.","zh-TW":"他被指控捏造證據。"},{"en":"The parts are fabricated in our factory.","zh-TW":"零件在我們工廠製造。"}]', '{"noun":"fabrication","verb":"fabricate"}', NULL, 3, 1288, NULL),
(1289, 'face', '/feɪs/', 'verb / noun', '{"zh-TW":["【主要意義-名詞/動詞】臉；面對","【次要意義-動詞】朝向；面向（某方向）","【次要意義-名詞】表面；外觀；正面","【次要意義-名詞】面子；聲譽"],"en":["[primary] the front part of the head; to look toward","[secondary - verb] to be positioned toward a particular direction","[secondary - noun] the surface or front of something","[secondary - noun] reputation or social standing"]}', NULL, 'face value / at face value / face the consequences / save face / lose face', '[{"en":"Do not take the contract terms at face value; read the fine print.","zh-TW":"不要只看合約條款的表面意思，要仔細閱讀細則。"},{"en":"The company managed to save face by issuing a public apology.","zh-TW":"公司通過發表公開道歉來保住了顏面。"},{"en":"The new building faces the main commercial district.","zh-TW":"新大樓面朝主要商業區。"}]', '{"adjective":"face-to-face, facing","noun":"facade"}', 'face value（表面價值/票面價值）、save face（保住面子）、at face value（按表面意思）均是 TOEIC 商業和社交文章的常見陷阱，face 的金融含義（票面）也常見。', 1, 1289, NULL),
(1290, 'facilitate', '/fəˈsɪlɪteɪt/', 'verb', '{"zh-TW":["促進；使便利"],"en":["to make an action or process easier"]}', NULL, 'facilitate communication/growth', '[{"en":"Technology facilitates remote collaboration.","zh-TW":"技術促進了遠端協作。"},{"en":"The mediator facilitated the discussion.","zh-TW":"調解人促進了討論。"}]', '{"noun":"facilitation/facilitator","verb":"facilitate"}', NULL, 4, 1290, 684),
(1291, 'facilitator', '/fəˈsɪlɪteɪtər/', 'noun', '{"zh-TW":["主持人；促進者"],"en":["a person who helps a group or process operate more effectively"]}', NULL, 'act as a facilitator / workshop facilitator', '[{"en":"The HR manager served as facilitator for the conflict resolution session.","zh-TW":"人力資源管理者擔任了衝突解決會議的主持人。"},{"en":"A skilled facilitator keeps discussions productive and on track.","zh-TW":"熟練的主持人使討論保持高效並按計劃進行。"}]', '{"verb":"facilitate","adjective":"facilitated"}', NULL, 4, 1291, NULL),
(1292, 'facilities', '/fəˈsɪlɪtiz/', 'noun', '{"zh-TW":["設施；設備"],"en":["equipment and services available at a place"]}', NULL, 'hotel facilities / use the facilities', '[{"en":"The hotel''s facilities include a gym and outdoor pool.","zh-TW":"飯店設施包括健身房和室外游泳池。"},{"en":"Conference facilities are available for business travelers.","zh-TW":"會議設施供商務旅客使用。"}]', '{"verb":"facilitate","adjective":"facilitated"}', NULL, 4, 1292, 359),
(1293, 'facility', '/fəˈsɪləti/', 'noun', '{"zh-TW":["設施；場所"],"en":["a building or place for a particular purpose"]}', NULL, 'manufacturing/training facility', '[{"en":"The company opened a new manufacturing facility.","zh-TW":"公司開設了新的生產設施。"},{"en":"Our facilities are available for conferences.","zh-TW":"我們的設施可供會議使用。"}]', '{"noun":"facility"}', NULL, 3, 1293, 31),
(1294, 'fact', '/fækt/', 'noun', '{"zh-TW":["事實"],"en":["something known to be true"]}', NULL, 'in fact / as a matter of fact', '[{"en":"In fact, sales increased by 20%.","zh-TW":"事實上，銷售增長了20%。"},{"en":"We need facts, not opinions.","zh-TW":"我們需要事實，不是意見。"}]', '{"noun":"fact","adjective":"factual","adverb":"factually"}', NULL, 1, 1294, NULL),
(1295, 'factor', '/ˈfæktər/', 'noun', '{"zh-TW":["因素；要素","因素"],"en":["a circumstance that contributes to a result"]}', '{"root":{"text":"fact","meaning":"make/do (做)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"促成某事發生的東西，即「因素」。"}', 'key/determining factor; key factor / risk factor / contributing factor', '[{"en":"Cost is a major factor in the decision.","zh-TW":"成本是決策中的主要因素。"},{"en":"Several factors contributed to the failure.","zh-TW":"幾個因素導致了失敗。"},{"en":"Cost is an important factor in this decision.","zh-TW":"成本是這個決策中的重要因素。"},{"en":"Several factors contributed to the delay.","zh-TW":"多項因素導致了延遲。"}]', '{"noun":"factor","verb":"factor","adjective":"factorial"}', NULL, 2, 1295, 360),
(1296, 'factoring', '/ˈfæktərɪŋ/', 'noun', '{"zh-TW":["應收帳款融資；保理"],"en":["selling accounts receivable to a third party at a discount for immediate cash"]}', NULL, 'invoice factoring / factoring company / factoring facility', '[{"en":"Factoring provided the small business with immediate working capital.","zh-TW":"保理為小企業提供了即時營運資金。"},{"en":"The company used factoring to bridge the gap between invoicing and payment.","zh-TW":"公司使用保理來彌補開票和收款之間的差距。"}]', '{"verb":"factor","noun":"factor"}', NULL, 3, 1296, NULL),
(1297, 'faculty', '/ˈfækəlti/', 'noun', '{"zh-TW":["全體教職員；院系"],"en":["the teaching staff of a university"]}', NULL, 'faculty member / faculty meeting', '[{"en":"The faculty voted on the proposal.","zh-TW":"教職員對提案進行了投票。"},{"en":"She''s a faculty member in the science department.","zh-TW":"她是理學院的教職員。"}]', NULL, NULL, 3, 1297, NULL),
(1298, 'fail', '/feɪl/', 'verb', '{"zh-TW":["失敗；未能"],"en":["to be unsuccessful; to neglect"]}', NULL, 'fail to meet/deliver', '[{"en":"The project failed to meet its objectives.","zh-TW":"該項目未能達成目標。"},{"en":"The business failed within two years.","zh-TW":"這家企業在兩年內倒閉了。"}]', '{"noun":"failure","verb":"fail"}', NULL, 1, 1298, NULL),
(1299, 'failure', 'ˈfeɪljər', 'noun', '{"zh-TW":["失敗；失誤","故障"],"en":["a lack of success","a breakdown"]}', NULL, 'system failure/product failure', '[{"en":"We must analyze the causes of failure.","zh-TW":"我們必須分析失敗的原因。"}]', '{"verb":"fail","adjective":"failed","adverb":"failingly"}', NULL, 3, 1299, NULL);